 * fu_input_stream_read_bytes:
 * @stream: a #GInputStream
 * @offset: offset in bytes into @stream to copy from
 * @count: maximum number of bytes to read
 * @error: (nullable): optional return location for an error
 *
 * Read a #GBytes from a stream in a safe way.
 *
 * NOTE: The returned buffer may be smaller than @count!
 *
 * Returns: (transfer full): buffer
 *
 * Since: 2.0.0
 **/
GBytes *
fu_input_stream_read_bytes(GInputStream *stream, gsize offset, gsize count, GError **error)
{
 g_autoptr(GByteArray) buf = NULL;
 g_return_val_if_fail(G_IS_INPUT_STREAM(stream), NULL);
 g_return_val_if_fail(error == NULL || *error == NULL, NULL);
 buf = fu_input_stream_read_byte_array(stream, offset, count, error);
 if (buf == NULL)
  return NULL;
 return g_byte_array_free_to_bytes(g_steal_pointer(&buf)); /* nocheck */
}

/**
 * fu_input_stream_size:
 * @stream: a #GInputStream
 * @val: (out): size in bytes
 * @error: (nullable): optional return location for an error
 *
 * Reads the total possible of the stream.
 *
 * If @stream is not seekable, %G_MAXSIZE is used as the size.
 *
 * Returns: %TRUE for success
 *
 * Since: 2.0.0
 **/
gboolean
fu_input_stream_size(GInputStream *stream, gsize *val, GError **error)
{
 g_return_val_if_fail(G_IS_INPUT_STREAM(stream), FALSE);
 g_return_val_if_fail(error == NULL || *error == NULL, FALSE);

 /* streaming from unseekable stream */
 if (!G_IS_SEEKABLE(stream) || !g_seekable_can_seek(G_SEEKABLE(stream))) {
  if (val != NULL)
      *val = G_MAXSIZE;
  return TRUE;
 }

 if (!g_seekable_seek(G_SEEKABLE(stream), 0, G_SEEK_END, NULL, error)) {
  g_prefix_error(error, "seek to end: ");
  return FALSE;
 }
 if (val != NULL)
  *val = g_seekable_tell(G_SEEKABLE(stream));

 /* success */
 * fu_bytes_new_offset:
 * @bytes: data blob
 * @offset: where subsection starts at
 * @length: length of subsection
 * @error: (nullable): optional return location for an error
 *
 * Creates a #GBytes which is a subsection of another #GBytes.
 *
 * Returns: (transfer full): a #GBytes, or #NULL if range is invalid
 *
 * Since: 1.8.2
 **/
GBytes *
fu_bytes_new_offset(GBytes *bytes, gsize offset, gsize length, GError **error)
{
 g_return_val_if_fail(bytes != NULL, NULL);
 g_return_val_if_fail(error == NULL || *error == NULL, NULL);

 /* optimize */
 if (offset == 0x0 && g_bytes_get_size(bytes) == length)
  return g_bytes_ref(bytes);

 /* sanity check */
 if (offset + length < length || offset + length > g_bytes_get_size(bytes)) {
  g_set_error(error,
          FWUPD_ERROR,
          FWUPD_ERROR_INVALID_DATA,
          "cannot create bytes @0x%02x for 0x%02x "
          "as buffer only 0x%04x bytes in size",
          (guint)offset,
          (guint)length,
          (guint)g_bytes_get_size(bytes));
  return NULL;
 }
 return g_bytes_new_from_bytes(bytes, offset, length);
}

/**
 * fu_bytes_get_data_safe:
 * @bytes: data blob
 * @bufsz: (out) (optional): location to return size of byte data
 * @error: (nullable): optional return location for an error
 *
 * Get the byte data in the #GBytes. This data should not be modified.
 * This function will always return the same pointer for a given #GBytes.
 *
 * If the size of @bytes is zero, then %NULL is returned and the @error is set,
 * which differs in behavior to that of g_bytes_get_data().
 *
 * This may be useful when calling g_mapped_file_new() on a zero-length file.
 *
 * Returns: a pointer to the byte data, or %NULL.
